using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;
public static class NurseAnatomyAudit {
 public static void Run(){try{
  string output=RebirthEntityStudio.RebirthNurseAnatomyFit.Output;EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);
  var model=UnityEngine.Object.Instantiate(AssetDatabase.LoadAssetAtPath<GameObject>(RebirthEntityStudio.RebirthNurseNativeAssembly.Folder+"/RebirthNurse_Authoring.prefab"));var body=model.GetComponentsInChildren<SkinnedMeshRenderer>(true).Single(r=>r.name=="LOD0");var bones=model.transform.Find("Origin").GetComponentsInChildren<Transform>(true).ToDictionary(t=>t.name);var rows=new List<string>();
  var source=AssetDatabase.LoadAssetAtPath<GameObject>(AssetDatabase.FindAssets("t:Model",new[]{RebirthEntityStudio.RebirthNurseReplacement.Input}).Select(AssetDatabase.GUIDToAssetPath).Single(p=>p.EndsWith(".fbx")));
  if(!source.GetComponentsInChildren<MeshFilter>(true).Any(r=>RebirthEntityStudio.RebirthNurseSourcePreservation.Hash(r.sharedMesh)==RebirthEntityStudio.RebirthNurseSourcePreservation.Hash(body.sharedMesh)))throw new Exception("Source geometry changed");rows.Add("Source LOD0 positions, normals, tangents, UVs, colours, indices: EXACT MATCH");
  var native=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/NativeReferences/Nurse/PrefabInstance/ZNurse.prefab");var nb=native.transform.Find("Origin").GetComponentsInChildren<Transform>(true).ToDictionary(t=>t.name);
  foreach(var b in bones.Values)if(b.name!="Origin"&&nb[b.name].parent.name!=b.parent.name)throw new Exception("Parent mismatch "+b.name);
  foreach(var joint in model.GetComponentsInChildren<CharacterJoint>(true)){var src=nb[joint.name].GetComponent<CharacterJoint>();if(joint.axis!=src.axis||joint.swingAxis!=src.swingAxis)throw new Exception("Joint axes changed");float distance=Vector3.Distance(joint.transform.TransformPoint(joint.anchor),joint.connectedBody.transform.TransformPoint(joint.connectedAnchor));if(distance>.0001f)throw new Exception("Disconnected joint");}
  rows.Add("Native Nurse skeleton parents, 87 nodes, 11 detail capsules, 11 rigidbodies, 10 CharacterJoints; joint axes/anchors: PASS");
  Physics.SyncTransforms();foreach(var pair in new[]{new[]{"Hips","Spine2"},new[]{"Head","Spine2"},new[]{"LeftArm","Spine2"},new[]{"RightArm","Spine2"},new[]{"LeftForeArm","LeftArm"},new[]{"RightForeArm","RightArm"},new[]{"LeftUpLeg","Hips"},new[]{"RightUpLeg","Hips"},new[]{"LeftLeg","LeftUpLeg"},new[]{"RightLeg","RightUpLeg"}}){var a=bones[pair[0]].GetComponent<CapsuleCollider>();var b=bones[pair[1]].GetComponent<CapsuleCollider>();bool overlap=Physics.ComputePenetration(a,a.transform.position,a.transform.rotation,b,b.transform.position,b.transform.rotation,out var direction,out var depth);rows.Add("Coverage join "+pair[0]+" / "+pair[1]+": "+overlap+" depth="+depth);if(!overlap)throw new Exception("Collider junction gap "+pair[0]+" / "+pair[1]);}
  var animator=model.GetComponent<Animator>();if(!animator.avatar.isValid||!animator.avatar.isHuman)throw new Exception("Avatar invalid");rows.Add("Humanoid avatar valid; native controller clips="+animator.runtimeAnimatorController.animationClips.Distinct().Count());
  foreach(string category in new[]{"walk","melee","pain"}){var clip=animator.runtimeAnimatorController.animationClips.First(c=>c.name.ToLowerInvariant().Contains(category));var rest=bones.Values.ToDictionary(t=>t,t=>t.position);AnimationMode.StartAnimationMode();AnimationMode.BeginSampling();AnimationMode.SampleAnimationClip(model,clip,Mathf.Min(.35f,clip.length*.4f));AnimationMode.EndSampling();var baked=new Mesh();body.BakeMesh(baked);if(baked.vertices.Any(v=>float.IsNaN(v.x)||float.IsInfinity(v.x)))throw new Exception("Nonfinite skin");rows.Add("Animation "+clip.name+": finite skinned vertices="+baked.vertexCount+" maxBoneMotion="+rest.Max(p=>Vector3.Distance(p.Key.position,p.Value)));UnityEngine.Object.DestroyImmediate(baked);AnimationMode.StopAnimationMode();}
  File.WriteAllLines(output+"/anatomy-audit.txt",rows);
  string build=output+"/BuildFinal_"+DateTime.Now.ToString("yyyyMMdd_HHmmss");var receipt=RebirthEntityStudio.RebirthEntityBundleBuilder.BuildAndVerify(RebirthEntityStudio.RebirthNurseNativeAssembly.PrefabPath,build);File.WriteAllText(output+"/final-build-path.txt",build);Debug.Log("NURSE_ANATOMY_AUDIT_DONE");
 }catch(Exception e){Debug.LogException(e);EditorApplication.Exit(1);}}
}

